/**
 * すべての動物に鳴かせる
 */
@GetMapping("/sounds")
public List<String> getAllSounds() {
    return animalService.makeAllAnimalsSound();
}

/**
 * すべての動物に鳴かせる（ポリモーフィズム）
 */
public List<String> makeAllAnimalsSound() {
    return animals.stream()
            .map(Animal::makeSound)
            .collect(Collectors.toList());
}

/**
 * 複雑なメソッド: すべての動物タイプの行動を実行
 */
public String performComplexActions() {
    StringBuilder result = new StringBuilder();
    result.append("=== All Animals Sound ===\n");
    makeAllAnimalsSound().forEach(sound -> result.append(sound).append("\n"));

    result.append("\n=== Mammal Actions ===\n");
    performMammalActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Dog Actions ===\n");
    performDogActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Golden Retriever Actions ===\n");
    performGoldenRetrieverActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Cat Actions ===\n");
    performCatActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Persian Cat Actions ===\n");
    performPersianCatActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Bird Actions ===\n");
    performBirdActions().forEach(action -> result.append(action).append("\n"));

    result.append("\n=== Sparrow Actions ===\n");
    performSparrowActions().forEach(action -> result.append(action).append("\n"));

    return result.toString();
}
